import os
import base64
import tempfile
from pathlib import Path

import faiss
import fitz  # PyMuPDF
import numpy as np
import streamlit as st
from groq import Groq
from sentence_transformers import SentenceTransformer


# ============================================================
# Cyber Law GPT
# RAG assistant grounded in the attached PECA PDF.
# The PDF is embedded so this project needs only 3 files:
# app.py, requirements.txt, readme.md
# ============================================================

APP_NAME = "Cyber Law GPT"
EMBEDDING_MODEL = os.getenv("EMBEDDING_MODEL", "sentence-transformers/all-MiniLM-L6-v2")
DEFAULT_GROQ_MODEL = os.getenv("GROQ_MODEL", "openai/gpt-oss-20b")

# The supplied PECA.pdf is embedded into this single Python file.
# On startup it is reconstructed into a temporary PDF and indexed.
PECA_PDF_B64 = """"""


def get_api_key():
    """Read the Groq API key from Streamlit secrets or environment variables."""
    try:
        key = st.secrets.get("GROQ_API_KEY")
        if key:
            return key
    except Exception:
        pass

    return os.getenv("GROQ_API_KEY")


def write_embedded_pdf():
    """Recreate the supplied PECA PDF in a temporary location."""
    temp_dir = Path(tempfile.gettempdir()) / "cyber_law_gpt"
    temp_dir.mkdir(parents=True, exist_ok=True)

    pdf_path = temp_dir / "PECA.pdf"

    if not pdf_path.exists() or pdf_path.stat().st_size == 0:
        pdf_path.write_bytes(base64.b64decode(PECA_PDF_B64))

    return pdf_path


def extract_pdf_chunks(pdf_path, chunk_size=1200, overlap=200):
    """
    Extract text page-by-page and create overlapping chunks.

    Keeping page numbers allows the app to show useful source references.
    """
    document = fitz.open(pdf_path)
    chunks = []

    for page_number, page in enumerate(document, start=1):
        text = page.get_text("text").replace("\x00", " ").strip()

        if not text:
            continue

        # Normalize excessive whitespace without changing the legal wording.
        text = " ".join(text.split())

        start = 0
        while start < len(text):
            end = min(start + chunk_size, len(text))
            chunk_text = text[start:end].strip()

            if chunk_text:
                chunks.append(
                    {
                        "text": chunk_text,
                        "page": page_number,
                        "source": "PECA.pdf",
                    }
                )

            if end >= len(text):
                break

            start = max(end - overlap, start + 1)

    document.close()
    return chunks


@st.cache_resource(show_spinner="Downloading the embedding model and building the legal index...")
def build_index():
    """
    Runs once per Streamlit process:
    1. Recreates the supplied PECA PDF.
    2. Extracts its text.
    3. Downloads/loads the SentenceTransformer model.
    4. Creates embeddings.
    5. Builds a FAISS vector index.
    """
    pdf_path = write_embedded_pdf()
    chunks = extract_pdf_chunks(pdf_path)

    if not chunks:
        raise RuntimeError("No readable text was found in the PECA PDF.")

    model = SentenceTransformer(EMBEDDING_MODEL)

    texts = [item["text"] for item in chunks]
    embeddings = model.encode(
        texts,
        normalize_embeddings=True,
        convert_to_numpy=True,
        show_progress_bar=False,
    ).astype("float32")

    index = faiss.IndexFlatIP(embeddings.shape[1])
    index.add(embeddings)

    return model, index, chunks


def retrieve(query, model, index, chunks, top_k=5):
    """Retrieve the most relevant PECA passages for a user question."""
    query_vector = model.encode(
        [query],
        normalize_embeddings=True,
        convert_to_numpy=True,
        show_progress_bar=False,
    ).astype("float32")

    scores, indices = index.search(query_vector, min(top_k, len(chunks)))

    results = []
    for score, idx in zip(scores[0], indices[0]):
        if idx < 0:
            continue

        item = dict(chunks[int(idx)])
        item["score"] = float(score)
        results.append(item)

    return results


def build_context(results):
    """Create a clearly labeled context block for the Groq model."""
    parts = []

    for number, item in enumerate(results, start=1):
        parts.append(
            f"[SOURCE {number} | PECA.pdf | Page {item['page']}]\n"
            f"{item['text']}"
        )

    return "\n\n".join(parts)


def generate_answer(question, context, technicality, response_size, language):
    """Generate a grounded answer using Groq."""
    api_key = get_api_key()

    if not api_key:
        raise RuntimeError(
            "GROQ_API_KEY is missing. Add it to Streamlit Secrets or the environment."
        )

    client = Groq(api_key=api_key)

    technicality_instructions = {
        "Beginner": "Use simple language and briefly explain legal terms.",
        "Intermediate": "Use clear legal and technical language with enough explanation.",
        "Advanced": "Use precise legal terminology and distinguish sections, conditions, and procedures.",
    }

    size_instructions = {
        "Short": "Answer in a concise format, preferably 3-6 bullets or short paragraphs.",
        "Medium": "Give a balanced answer with the applicable section, explanation, and relevant consequence.",
        "Detailed": "Give a thorough answer with the applicable section(s), conditions, reasoning, punishment/procedure if stated, and practical interpretation strictly supported by the sources.",
    }

    system_prompt = f"""
You are {APP_NAME}, a retrieval-augmented legal information assistant.

PRIMARY SOURCE:
The only legal source for substantive answers in this application is the supplied
Prevention of Electronic Crimes Act, 2016 (PECA) PDF, including the amendments and
text contained in that supplied document.

GROUNDING RULES:
1. Answer only from the retrieved source passages.
2. Identify the relevant PECA section number whenever the source supports it.
3. Do not invent sections, punishments, procedures, authorities, definitions, or legal conclusions.
4. If the retrieved passages do not contain enough information, say:
   "The supplied PECA document does not provide enough information to answer this specific question."
   Then explain what information is actually supported by the retrieved text.
5. If the question is outside the scope of the supplied PECA document, say that clearly.
6. Do not treat a possibility as a definite legal conclusion. Use wording such as
   "the section provides..." or "the conduct described may fall under..." when appropriate.
7. Do not use outside legal knowledge, websites, or other laws to fill missing information.
8. Always include source references such as "PECA Section 16, Page 20" when available.
9. Do not reproduce long portions of the law. Summarize the relevant provision.

STYLE:
Technicality: {technicality}. {technicality_instructions[technicality]}
Response size: {response_size}. {size_instructions[response_size]}
Language: {language}.

IMPORTANT:
This is legal information, not a substitute for advice from a qualified lawyer or a court.
"""

    user_prompt = f"""
QUESTION:
{question}

RETRIEVED PECA SOURCE PASSAGES:
{context}

Write the answer using only the retrieved passages.
"""

    response = client.chat.completions.create(
        model=DEFAULT_GROQ_MODEL,
        messages=[
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": user_prompt},
        ],
        temperature=0.1,
        max_tokens=1800 if response_size == "Detailed" else 1000,
    )

    return response.choices[0].message.content


# --------------------------- UI -----------------------------

st.set_page_config(
    page_title=APP_NAME,
    page_icon="⚖️",
    layout="wide",
)

st.title("⚖️ Cyber Law GPT")
st.caption("RAG-based question answering grounded in the supplied Prevention of Electronic Crimes Act, 2016 (PECA) PDF.")

with st.sidebar:
    st.header("Answer Settings")

    technicality = st.selectbox(
        "Technicality level",
        ["Beginner", "Intermediate", "Advanced"],
        index=0,
        help="Controls how technical the explanation should be.",
    )

    response_size = st.selectbox(
        "Response size",
        ["Short", "Medium", "Detailed"],
        index=1,
        help="Controls the amount of explanation returned.",
    )

    language = st.selectbox(
        "Answer language",
        ["English", "Urdu", "Roman Urdu"],
        index=0,
        help="Choose the language used for the generated explanation.",
    )

    top_k = st.slider(
        "Number of source passages",
        min_value=2,
        max_value=8,
        value=5,
        help="More passages can improve recall but may add less-relevant context.",
    )

    st.divider()

    st.subheader("Model")
    st.write(f"Groq model: `{DEFAULT_GROQ_MODEL}`")
    st.write(f"Embedding model: `{EMBEDDING_MODEL}`")

    st.divider()
    st.info(
        "The legal source is the supplied PECA PDF. "
        "The app is designed to avoid answering from unsupported outside law."
    )

    if st.button("Clear chat"):
        st.session_state.messages = []
        st.rerun()


if "messages" not in st.session_state:
    st.session_state.messages = []


try:
    embedding_model, faiss_index, chunks = build_index()
    st.success(f"Legal knowledge base ready: {len(chunks)} text chunks indexed with FAISS.")
except Exception as error:
    st.error(f"Startup/indexing error: {error}")
    st.stop()


# Display chat history.
for message in st.session_state.messages:
    with st.chat_message(message["role"]):
        st.markdown(message["content"])

question = st.chat_input(
    "Ask about a cyber-law situation, PECA section, offence, punishment, procedure, or definition..."
)

if question:
    st.session_state.messages.append(
        {"role": "user", "content": question}
    )

    with st.chat_message("user"):
        st.markdown(question)

    with st.chat_message("assistant"):
        with st.spinner("Finding the relevant PECA provisions..."):
            results = retrieve(
                question,
                embedding_model,
                faiss_index,
                chunks,
                top_k=top_k,
            )

            context = build_context(results)

            try:
                answer = generate_answer(
                    question=question,
                    context=context,
                    technicality=technicality,
                    response_size=response_size,
                    language=language,
                )
            except Exception as error:
                answer = f"Unable to generate the answer: {error}"

        st.markdown(answer)

        with st.expander("Retrieved PECA sources"):
            for number, item in enumerate(results, start=1):
                st.markdown(
                    f"**Source {number} — PECA.pdf, Page {item['page']} "
                    f"(similarity: {item['score']:.3f})**"
                )
                st.write(item["text"])

        st.caption(
            "Legal-information notice: answers are grounded in the supplied document "
            "and are not a substitute for professional legal advice."
        )

    st.session_state.messages.append(
        {"role": "assistant", "content": answer}
    )
